                  },
                  {
                    "type": "code",
                    "lang": "js",
                    "code": "export default {\n  type: 'code',\n  title: 'Rename Button prop kind to variant',\n  fileExtensions: ['.tsx', '.ts'],\n  transform(file, api) {\n    const j = api.jscodeshift;\n    const root = j(file.source);\n    // ...rewrite the AST...\n    return root.toSource();\n  },\n};",
                    "label": "Code codemod (type: code)"
